```javascript[]
class Solution {
  removeKdigits(nums, k) {
    const n = nums.length;
    const stack = [];
    let i = 0;

    while (i < n && k > 0) {
      if (stack.length > 0 && stack[stack.length - 1] > Number(nums[i])) {
        stack.pop();
        k--;
      } else {
        stack.push(Number(nums[i]));
        i++;
      }
    }

    // Push remaining elements
    while (i < n) {
      stack.push(Number(nums[i]));
      i++;
    }

    // If still k>0, eg: 12345
    while (k > 0) {
      stack.pop();
      k--;
    }

    // Remove leading zeros if any
    i = 0;
    while (stack[i] === 0) {
      i++;
    }

    const ans = stack.filter((_, idx) => idx >= i).join("");

    return ans ? ans : "0";
  }
}

```

